// The only persistence boundary for the editable greeting text.
// The storage object is injected (the browser passes `localStorage`) so this
// module stays free of globals and is testable with a plain in-memory fake.

export const TEXT_KEY = 'hello-world.text';
export const DEFAULT_TEXT = 'hello world';

/**
 * @param {{getItem(key: string): string | null}} storage
 * @returns {string} the stored text, or DEFAULT_TEXT when unset or unreadable
 */
export function loadText(storage) {
  try {
    const stored = storage.getItem(TEXT_KEY);
    return stored === null ? DEFAULT_TEXT : stored;
  } catch (error) {
    console.error('[text-store] load failed', error);
    return DEFAULT_TEXT;
  }
}

/**
 * @param {{setItem(key: string, value: string): void}} storage
 * @param {string} text
 * @returns {boolean} true when the text was stored, false when the write failed
 */
export function saveText(storage, text) {
  try {
    storage.setItem(TEXT_KEY, text);
    return true;
  } catch (error) {
    console.error('[text-store] save failed', error);
    return false;
  }
}

